connectionHandler.test.ts mocks handleMessage (it tests the handler's dispatch, not the message handler's ordering) — my queue in messageHandler doesn't affect it ✓. handshake.test.ts:61 sends a ping on a fresh socket (first frame) ✓ unaffected.

Nobody sends a ping mid-turn expecting a prompt pong. So the per-socket queue for the non-turn path is safe.

Now implement it in messageHandler.ts. Current handleMessage (after my edits):

```ts
export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () =>
        answerInTurn(ws, session, orchestrator, validation, signal, sessionStore)
      );
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore));
  };
}
```

New version:

```ts
export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  // Each socket's last non-turn answer, so a ping cannot be answered before the frame ahead of it was answered too.
  const answers = new WeakMap<WebSocket, Promise<void>>();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () =>
        answerInTurn(ws, session, orchestrator, validation, signal, sessionStore)
      );
    }
    // In arrival order per socket, but never behind a turn: a history request waits for the frame ahead of it, not for a stream.
    const answer = (answers.get(ws) ?? Promise.resolve()).catch(() => undefined).then(() =>
      wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore))
    );
    answers.set(ws, answer);
    return answer;
  };
}
