    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () =>
        answerInTurn(ws, session, orchestrator, validation, signal, sessionStore)
      );
    }
    // Off the lock and beside the turns: a history request waits for the frame ahead of it, never for a streaming answer.
    const answer = (answers.get(ws) ?? Promise.resolve())
      .catch(() => undefined)
      .then(() => wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore)));
    answers.set(ws, answer);
    return answer;
  };
}

